'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(x||0),num=x=>Number(x||0).toFixed(1),pct=x=>Math.round(x*100)+'%';
const icons={map:'M3 3h6v6H3z M15 15h6v6h-6z M15 3h6v6h-6z M6 9v9h9 M9 6h6',box:'M3 7l9-4 9 4v11l-9 4-9-4z M3 7l9 4 9-4 M12 11v11',chart:'M4 20V4 M4 20h17 M8 16v-4 M13 16V6 M18 16v-7',compare:'M5 3v18 M19 3v18 M5 7h9l-3-3 M14 7l-3 3 M19 17h-9l3-3 M10 17l3 3',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',play:'M8 5l11 7-11 7z',pause:'M8 5v14 M16 5v14',step:'M5 5l10 7-10 7z M19 5v14',reset:'M4 10a8 8 0 1 1 1 8 M4 4v6h6',branch:'M7 3v14a3 3 0 1 0 3 3 M7 7h7a3 3 0 0 0 3-3 M17 2v4',arrow:'M5 12h14 M14 7l5 5-5 5',plus:'M12 5v14 M5 12h14',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',upload:'M12 16V4 M7 9l5-5 5 5 M4 17v4h16v-4',info:'M12 10v7 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',people:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-2a7 7 0 0 1 14 0v2 M17 5a4 4 0 0 1 0 8 M19 16a5 5 0 0 1 3 5',user:'M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M4 21v-2a8 8 0 0 1 16 0v2',close:'M6 6l12 12 M18 6L6 18',clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'M5 12l4 4L20 5',wallet:'M3 6h17v15H3z M3 6V3h14 M15 11h6v5h-6z',file:'M5 3h10l4 4v14H5z M14 3v5h5 M8 12h8 M8 16h6'};
const icon=k=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[k]||icons.map}"/></svg>`;
const btn=(text,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;

// UI edits live in a separate draft. Only explicit apply actions affect the engine.
const KEY='qq-studio-lab-v1', THEME_KEY='qq-studio-appearance';
let state=QQ.fresh(),saved=[],draft=QQ.clone(state.config),view='setup',stepIndex=0;
let archives=[],checkpointInfo=[],recoveryFiles=[],saveTimer=null,backend=null,saveWriter=null;
let loading=typeof indexedDB!=='undefined',saveStatus='saved',storeReason='',localRevision=null;
let selection=null,running=false,timer=null,speed=1,theme='light',storeError=false,recoveryRaw=null;
let filter='active',search='',toastTimer,modalFocus=null,expandedService=0;
try{
  const raw=localStorage.getItem(KEY);localRevision=raw??null;
  if(raw){try{installWorkspace(MEIQQWorkspace.parseText(raw));}catch(e){recoveryRaw=raw;storeError=true;saveStatus='error';}}
  const chosen=localStorage.getItem(THEME_KEY);if(['light','dark','terminal'].includes(chosen))theme=chosen;
}catch(e){storeError=true;}
document.documentElement.dataset.theme=theme;
const steps=['Services','Customers','Team & time','Cash & timing'];
const stageOwner={inquiry:'Client',quote:'You',design:'China team',review:'You',approval:'Client',production:'Supplier',delivery:'You',payment:'Client',complete:'Complete',lost:'Declined'};
const stageNumber={inquiry:1,quote:2,design:3,review:4,approval:5,production:6,delivery:7,payment:8};
const shortLabels={inquiry:'New inquiry',quote:'Prepare quote',design:'Create design',review:'Review design',approval:'Client approves',production:'Print order',delivery:'Deliver work',payment:'Collect balance',complete:'Complete',lost:'Declined'};
function dirty(){return JSON.stringify(draft)!==JSON.stringify(state.config);}
function currentWorkspace(){
 const files=QQ.clone(recoveryFiles);
 if(recoveryRaw&&!files.some(f=>f.text===recoveryRaw))files.push({name:'Unreadable original save',text:recoveryRaw});
 return {state,saved,draft,checkpointInfo,recoveryFiles:files};
}
function installWorkspace(data){
 state=data.state;saved=data.saved;draft=data.draft;checkpointInfo=data.checkpointInfo;
 recoveryFiles=data.recoveryFiles;archives=data.archives||[];view=state.day?'map':'setup';
}
function saveLabel(){return loading?'Opening saved workspace…':recoveryRaw?'Original save preserved. Download a backup of any new work before closing.':storeError?(storeReason||'Changes are not saved. Download a backup before closing.'):saveStatus==='pending'?'Unsaved draft changes…':saveStatus==='saving'?'Saving workspace…':'Workspace saved in this browser.';}
function updateSaveStatus(){const el=$('#save-status');if(el){el.textContent=saveLabel();el.className='save-status '+(storeError?'negative':'');}const note=$('#draft-summary .save-note');if(note)note.textContent=saveLabel();}
function persistenceStatus(status,error){storeReason=error?.code==='STALE_WORKSPACE'?'Another MEIQQ window saved changes. Back up this window before reopening.':'';saveStatus=status==='saved'&&saveTimer!==null?'pending':status;storeError=status==='error';updateSaveStatus();}
function save(){
 clearTimeout(saveTimer);saveTimer=null;
 if(loading||recoveryRaw){updateSaveStatus();return;}
 try{
  const text=MEIQQWorkspace.serialize(currentWorkspace(),archives);
  if(saveWriter)saveWriter.push(text);
  else {if((localStorage.getItem(KEY)??null)!==localRevision){const e=Error('Another window changed this workspace.');e.code='STALE_WORKSPACE';throw e;}localStorage.setItem(KEY,text);localRevision=text;persistenceStatus('saved');}
 }catch(e){persistenceStatus('error',e);}
}
function scheduleSave(){clearTimeout(saveTimer);saveStatus='pending';updateSaveStatus();saveTimer=setTimeout(save,300);}
async function initializeStorage(){
 if(!loading){updateSaveStatus();return;}
 try{
  backend=await MEIQQStorage.connect(indexedDB,KEY);
  if(backend.raw){try{installWorkspace(MEIQQWorkspace.parseText(backend.raw));recoveryRaw=null;storeError=false;}catch(e){recoveryRaw=backend.raw;storeError=true;}}
  saveWriter=MEIQQStorage.writer(backend.write,persistenceStatus);
 }catch(e){backend=null;}
 loading=false;render();save();
}
function archiveCurrent(label){MEIQQWorkspace.archive(archives,currentWorkspace(),label);}
function openImportedWorkspace(data){
 const nextArchives=QQ.clone(archives);
 for(const a of data.archives||[])MEIQQWorkspace.archive(nextArchives,a.workspace,a.label);
 MEIQQWorkspace.archive(nextArchives,currentWorkspace());
 MEIQQWorkspace.serialize(data,nextArchives);
 installWorkspace({...data,archives:nextArchives});recoveryRaw=null;selection=null;
}

function stop(){clearInterval(timer);timer=null;running=false;}
function toast(message){clearTimeout(toastTimer);$('#toast').className='toast';$('#toast').textContent=message;toastTimer=setTimeout(()=>{$('#toast').className='';$('#toast').textContent='';},4500);}
function badge(text,kind=''){return `<span class="badge ${kind}">${esc(text)}</span>`;}
function metric(label,value,note,kind=''){return `<div class="metric ${kind}"><label>${label}</label><strong>${value}</strong><small>${note}</small></div>`;}
function title(){return {setup:'Set up your business',map:'Watch the work move',projects:'Find a project',finances:'Understand the results',scenarios:'Compare your experiments',about:'How this model works'}[view];}
function render(){
  const m=QQ.metrics(state);
  $('#root').innerHTML=`<div class="app ${running?'running':''}"><aside class="sidebar"><div class="brand"><div class="brandmark" aria-hidden="true">M</div><span>MEIQQ</span></div><div class="subbrand">BUSINESS SIMULATOR</div><nav>${[['setup','settings','1. Set up'],['map','map','2. Run business'],['finances','chart','3. Review results']].map(([v,i,n])=>btn(icon(i)+`<span>${n}</span>`,'view','navbutton '+(view===v?'active':''),`data-view="${v}" title="${n}"`)).join('')}<div class="navlabel">EXPLORE</div>${[['projects','file','Projects'],['scenarios','compare','Scenarios'],['about','info','Model guide']].map(([v,i,n])=>btn(icon(i)+`<span>${n}</span>`,'view','navbutton '+(view===v?'active':''),`data-view="${v}" title="${n}"`)).join('')}</nav><div class="sidebottom"><div class="sideinfo"><b>Hypothetical business</b><p>Test your ideas with editable assumptions.</p>${btn('Open worked example','example','small')}</div></div></aside><div class="shell"><header class="topbar"><div class="crumb"><b>${esc(state.config.name)}</b><span class="tag">PROTOTYPE 03 · A</span></div><div class="topactions"><label class="theme-picker"><span>Appearance</span><select id="appearance" aria-label="Appearance">${[['light','Light'],['dark','Dark'],['terminal','Terminal']].map(([v,n])=>`<option value="${v}" ${theme===v?'selected':''}>${n}</option>`).join('')}</select></label>${btn(icon('download')+'Backup','backup','small')}${btn(icon('upload')+'Open backup','import','small')}</div></header><div id="save-status" class="save-status" role="status" aria-live="polite">${esc(saveLabel())}</div><main class="workspace"><div class="heading"><div><div class="eyebrow">${view==='setup'?'DESIGN YOUR EXPERIMENT':'DAY '+state.day+' OF '+state.config.months*30}</div><h1>${title()}</h1><p class="muted">${view==='setup'?'Change your draft, review the impact, then apply it.':view==='map'?'Each card is real simulated work. Click a stage or project to understand it.':view==='finances'?'Money in the bank, profit and your time are different measures.':view==='projects'?'Search clients, filter work, and inspect each project.':view==='scenarios'?'Save checkpoints and compare runs at the same simulated day.':'Transparent assumptions, rules and limitations.'}</p></div>${view!=='setup'?btn(icon('branch')+'Branch scenario','branch'):badge('All values are editable assumptions')}</div>${recoveryRaw?`<div class="banner danger"><b>Your previous save could not be read.</b> It has not been overwritten. ${btn('Download original save','recover','small')} Open a valid backup to recover.</div>`:''}${recoveryFiles.length?`<div class="banner warn">${recoveryFiles.length} original draft or save file(s) preserved for recovery. ${btn('View recovery files','view','small','data-view="scenarios"')}</div>`:''}${state.blocked?`<div class="banner warn"><b>Cash shortfall paused the run.</b> ${esc(state.blocked.note)} · ${money(state.blocked.gap)} needed. ${btn('Resolve shortfall','cash','small')}</div>`:''}${dirty()&&view!=='setup'?`<div class="banner"><b>You have unapplied setup changes.</b> The clock still uses your last applied settings. ${btn('Review changes','view','small','data-view="setup"')}</div>`:''}${view==='setup'?setupView():view==='map'?mapView(m):view==='projects'?projectsView():view==='finances'?financeView(m):view==='scenarios'?scenariosView():aboutView()}</main>${clock()}</div></div>`;
}
function field(label,key,value,options={}){
 const path=options.path||key,id='input-'+path.replace(/\./g,'-');const suffix=options.suffix||'';
 const attrs=`data-input="${esc(path)}" ${options.percent?'data-percent="true"':''} id="${id}"`;
 return `<div class="input-field"><label for="${id}">${label}</label>${options.options?`<select ${attrs}>${options.options.map(([v,n])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${n}</option>`).join('')}</select>`:`<div class="input-wrap"><input ${attrs} type="${options.text?'text':'number'}" value="${esc(options.percent?QQ.round(value*100):value)}" ${options.text?'maxlength="100"':`min="${options.min??0}" max="${options.max??1000000}" step="${options.step??1}"`} ${options.disabled?'disabled':''}>${suffix?`<span>${suffix}</span>`:''}</div>`}<small>${options.help||' '}</small><span class="field-error" id="error-${id}" aria-live="polite"></span></div>`;
}
function checkbox(label,path,value,help=''){return `<label class="checkrow"><input type="checkbox" data-input="${path}" ${path.startsWith('uncertainty.')&&!draft.realism?'disabled':''} ${value?'checked':''}><span><b>${label}</b>${help?`<small>${help}</small>`:''}</span></label>`;}
function setupView(){return `<div class="setup-layout"><div><div class="setup-steps" role="tablist" aria-label="Setup steps">${steps.map((n,i)=>`<button role="tab" aria-selected="${stepIndex===i}" data-action="setup-step" data-step="${i}" class="${stepIndex===i?'active':''}"><span>${i+1}</span>${n}</button>`).join('')}</div><section class="panel setup-body">${stepIndex===0?serviceInputs():stepIndex===1?customerInputs():stepIndex===2?teamInputs():cashInputs()}<div class="step-footer">${stepIndex?btn('← Back','setup-step','','data-step="'+(stepIndex-1)+'"'):'<span></span>'}${stepIndex<3?btn('Next: '+steps[stepIndex+1]+' →','setup-step','primary','data-step="'+(stepIndex+1)+'"'):btn('Review & apply','review','primary')}</div></section></div><aside class="setup-summary" id="draft-summary">${draftSummary()}</aside></div>`;}
function serviceInputs(){const total=draft.services.reduce((a,s)=>a+s.weight,0);return `<div class="section-heading"><div><div class="eyebrow">STEP 1 / WHAT YOU SELL</div><h2>Define each offering</h2><p>A price, a deliverable and the work needed to produce it.</p></div>${btn(icon('plus')+'Add service','add-service','small')}</div><div class="banner compact"><b>Inquiry mix:</b> split 100% of incoming requests among your services. ${btn('Balance shares equally','balance','small')}</div><div class="mix-status" id="mix-status">Total share: ${QQ.round(total)}%</div>${draft.services.map((s,i)=>`<details class="service-editor" ${i===expandedService?'open':''}><summary><span class="service-dot" style="background:${s.color}"></span><span>${esc(s.name)}</span><small>${money(s.price)} · ${s.recurring?'Monthly':'One-off'}</small>${icon('settings')}</summary><div class="service-fields"><div class="formgrid">${field('Service name','name',s.name,{text:true,path:`services.${i}.name`})}${field('What the client receives','deliverable',s.deliverable,{text:true,path:`services.${i}.deliverable`})}${field('Client price','price',s.price,{path:`services.${i}.price`,suffix:'$ / project',help:'The full price, before any deposit.'})}${field('Inquiry share','weight',s.weight,{path:`services.${i}.weight`,max:100,suffix:'%',step:1,help:'How many new requests are for this service?'})}${field('Designer work per project','hours',s.hours,{path:`services.${i}.hours`,max:500,step:0.25,suffix:'hours'})}${field('Your review work per project','review',s.review,{path:`services.${i}.review`,max:100,step:0.25,suffix:'hours'})}${field('Printing + shipping cost','print',s.print,{path:`services.${i}.print`,suffix:'$ / project',help:'Enter 0 for digital delivery; printing is skipped.'})}${field('Purchase pattern','recurring',String(s.recurring),{path:`services.${i}.recurring`,options:[['false','One-off project'],['true','Monthly subscription']]})}</div><div class="service-actions">${btn('Duplicate','duplicate','small',`data-index="${i}"`)}${draft.services.length>1?btn('Remove from draft','remove-service','small ghost',`data-index="${i}"`):''}<span class="helper">Existing projects keep their agreed service.</span></div></div></details>`).join('')}`;}
function customerInputs(){const c=draft;return `<div class="eyebrow">STEP 2 / WHERE WORK COMES FROM</div><h2>Choose a workload</h2><p class="helper">Demand is an assumption. Increasing prices does not automatically reduce inquiries.</p><div class="formgrid">${field('How do inquiries arrive?','acquisition',c.acquisition,{options:[['preset','I set the number of inquiries'],['sales','My outreach generates inquiries']]})}${c.acquisition==='preset'?field('New inquiries each month','inquiries',c.inquiries,{max:500,suffix:'requests',help:'Requests for quotes, before sales conversion.'}):field('Your weekly outreach time','outreachHours',c.outreachHours,{max:120,step:0.5,suffix:'hours',help:'Uses part of your total weekly availability.'})}${c.acquisition==='sales'?field('Inquiries per outreach hour','leadsPerHour',c.leadsPerHour,{max:100,step:0.5,suffix:'requests',help:'An editable response assumption.'}):''}${field('Quotes that become paid work','conversion',c.conversion,{max:100,percent:true,suffix:'%',help:'70% means about 7 accepted quotes out of 10.'})}${field('Subscription clients who renew','retention',c.retention,{max:100,percent:true,suffix:'%',help:'Renewal is considered after the previous cycle is paid.'})}${field('One-off clients who order again','repeat',c.repeat,{max:100,percent:true,suffix:'%',help:'Returning requests arrive 30 days after final payment.'})}</div><div class="banner compact">New orders ≈ inquiries × conversion. Recurring and repeat clients are added during the simulation.</div>`;}
function teamInputs(){const c=draft;return `<div class="eyebrow">STEP 3 / WHO DOES THE WORK</div><h2>Set time and labor costs</h2><p class="helper">A five-day working week. Your time is shared across outreach, quoting, review and delivery.</p><div class="formgrid">${field('Your available time','ownerHours',c.ownerHours,{max:120,step:0.5,suffix:'hours / week'})}${field('Value of your time','ownerTarget',c.ownerTarget,{max:1000,suffix:'$ / hour',help:'An economic target; no cash is paid to you.'})}${field('Number of designers','designers',c.designers,{max:50,suffix:'people'})}${field('Availability of each designer','designerHours',c.designerHours,{max:120,step:0.5,suffix:'hours / week'})}${field('Designer labor cost','designerRate',c.designerRate,{max:1000,step:0.5,suffix:'$ / hour',help:'Paid for hours actually worked.'})}${field('Your work to prepare a quote','quoteHours',c.quoteHours,{max:24,step:0.1,suffix:'hours / inquiry'})}${field('Your work to deliver a project','deliveryHours',c.deliveryHours,{max:24,step:0.1,suffix:'hours / delivery'})}${field('When work is waiting, handle…','priority',c.priority,{options:[['deadline','Earliest deadline first'],['fifo','Oldest project first']]})}</div><div class="banner compact">You can prioritize an individual project from its detail panel. That overrides the normal queue order.</div>`;}
function cashInputs(){const c=draft;return `<div class="eyebrow">STEP 4 / MONEY AND COMMITMENTS</div><h2>Set payments and deadlines</h2><div class="formgrid">${field('Starting cash','startingCash',c.startingCash,{max:1e8,suffix:'$',help:state.day?'Requires a new run. Use Add funding for current cash.':'Cash available on day 0.'})}${field('Software and other overhead','overhead',c.overhead,{max:1e7,suffix:'$ / month'})}${field('Client deposit','deposit',c.deposit,{percent:true,max:100,suffix:'%',help:'Received when a quote is accepted.'})}${field('Final balance due after delivery','paymentDays',c.paymentDays,{max:90,suffix:'calendar days'})}${field('Client approval time','approvalDays',c.approvalDays,{max:30,suffix:'calendar days'})}${field('Print supplier turnaround','printDays',c.printDays,{max:90,suffix:'calendar days'})}${field('Promise delivery within','leadDays',c.leadDays,{min:1,max:180,suffix:'calendar days',help:'Measured from acceptance of the quote.'})}${field('Scenario name','name',c.name,{text:true})}</div><details class="advanced"><summary>Optional uncertainty & repeatability</summary><p class="helper">Begin with predictable projects. Switch on specific uncertainties to stress-test your setup.</p>${checkbox('Enable uncertain project outcomes','realism',c.realism)}<div class="uncertainty-grid">${[['complexity','Different design complexity'],['revisions','Extra client revision'],['approval','Slower client approval'],['supplier','Print supplier delays'],['payment','Late final payments']].map(([k,l])=>checkbox(l,'uncertainty.'+k,c.uncertainty[k])).join('')}</div>${field('Workload seed','seed',c.seed,{max:1e9,help:'Same seed + same settings = same replay. Changing it requires a new run.'})}</details>`;}
function mixValid(){return Math.abs(draft.services.reduce((n,s)=>n+s.weight,0)-100)<0.01;}
function draftError(){try{QQ.validateConfig(draft);if(!mixValid())return 'Service inquiry shares must add up to 100%. Adjust them or use Balance shares equally.';return '';}catch(e){return e.message;}}
function workloadRow(label,used,available){const ratio=available?used/available:used?Infinity:0;return `<div class="capacity-row"><div><b>${label}</b><span>${num(used)} / ${num(available)} h</span></div><div class="track"><div class="fill ${ratio>1?'warn':''}" style="width:${Math.min(100,ratio*100)}%"></div></div><small>${available===0&&used>0?'No capacity available':ratio>1?num(used-available)+' hours over capacity':num(Math.max(0,available-used))+' hours spare'}</small></div>`;}
function draftSummary(){const error=draftError(),changed=dirty();let e;try{e=QQ.estimate(draft);}catch(err){}return `<section class="panel summary-card"><div class="eyebrow">DRAFT PREVIEW · FIRST 30 DAYS</div><h2>What your setup implies</h2><p class="helper">22 working days. New business only, before queue delays and returning clients.</p>${error?`<div class="banner danger" role="alert">${esc(error)}</div>`:''}${!error&&e&&Object.values(e).every(v=>typeof v!=='number'||!Number.isNaN(v))?`<div class="summary-numbers"><div><strong>${num(e.orders)}</strong><small>Expected new orders</small></div><div><strong>${money(e.profit)}</strong><small>Potential operating result</small></div></div>${workloadRow('Your time',e.owner,e.ownerCapacity)}${workloadRow('Design team',e.hours,e.designCapacity)}<div class="minirow"><span>Potential revenue</span><b>${money(e.revenue)}</b></div><div class="minirow"><span>After valuing your time</span><b>${money(e.surplus)}</b></div>${e.ownerLoad>1||e.designLoad>1?'<div class="banner warn compact">This workload exceeds available hours. Run the simulation to see what gets delayed.</div>':''}${draft.acquisition==='sales'&&draft.outreachHours>draft.ownerHours?'<p class="error-text">Outreach is capped by your available hours and leaves no time for quoting.</p>':''}`:''}<div class="divider"></div><div class="draft-state">${changed?badge('Unapplied changes','warn'):badge('Matches current settings')}</div><p class="helper">${state.day?'Apply changes to future work, or start a fresh comparison.':'Apply your setup, then start from day 0.'}</p>${btn(changed?'Review & apply changes':'Go to workflow','review','primary full',error?'disabled':'')}${changed?btn('Cancel all draft changes','discard','ghost full'):''}<div class="save-note">${esc(saveLabel())}</div></section>`;}
function updatePreview(){const panel=$('#draft-summary');if(panel)panel.innerHTML=draftSummary();const mix=$('#mix-status');if(mix){mix.textContent='Total share: '+QQ.round(draft.services.reduce((n,s)=>n+s.weight,0))+'%'+(mixValid()?' · ready':' · must equal 100%');mix.className='mix-status '+(mixValid()?'positive':'negative');}scheduleSave();}
function mapView(m){const b=QQ.bottleneck(state);return `${state.day===0?`<div class="welcome-run"><div><h2>Ready when you are.</h2><p>Press <b>1 day</b> to follow the first inquiry, or <b>Run</b> to watch the business progress.</p></div>${btn('Open worked example','example','soft')}</div>`:''}<div class="metrics">${metric('Cash available',money(state.cash),'Receipts minus payments','accent')}${metric('Operating result',money(m.profit),'Delivered revenue minus all incurred costs',m.profit<0?'negative':'')}${metric('Your time',num(state.ownerHours)+' h',money(m.effective)+' per owner hour')}${metric('Late open deliveries',m.late,m.overduePayments+' overdue final payments',m.late?'negative':'')}</div><div class="workgrid"><div><section class="panel"><div class="panelhead"><div><h2>From inquiry to payment</h2><p class="helper">Numbered steps show order; lanes show responsibility.</p></div><span class="tag">${m.active} ACTIVE</span></div><div class="flow-strip">${QQ.STAGES.filter(s=>s!=='complete').map(s=>btn(`<span>${stageNumber[s]}</span>${shortLabels[s]}`,'stage','flow-step '+(selection?.type==='stage'&&selection.id===s?'selected':''),`data-id="${s}"`)).join('')}</div><div class="lanes">${[['Clients','Your customers','people',['inquiry','approval','payment']],['You','Sales, quality & delivery','user',['quote','review','delivery']],['China team','Design & revisions','people',['design']],['Suppliers','Printed work only','box',['production']]].map(([n,h,i,stages])=>`<section class="work-lane"><div class="lane-heading">${icon(i)}<div><h3>${n}</h3><small>${h}</small></div></div><div class="stage-grid ${stages.length===1?'single':''}">${stages.map(s=>stageCard(s,b)).join('')}</div></section>`).join('')}</div><div class="mapfooter">Digital-only work skips step 6. ${btn(m.complete+' completed projects','filter-complete','small')}</div></section><div class="insight-card panel"><h2>${b?'Where work is collecting':'What to look for'}</h2>${b?`<p><b>${shortLabels[b.stage]}</b> has ${b.count} projects and ${num(b.hours)} hours remaining. The oldest has waited ${b.oldest} days.</p><p class="helper">${b.stage==='design'?'Designers share their available hours.':'Quotes, review and delivery all compete for your available time.'} Client and supplier waiting time is tracked separately.</p><div class="actions">${btn('Inspect this queue','stage','soft','data-id="'+b.stage+'"')}${btn('Adjust team capacity','team','small')}</div>`:'<p class="helper">Advance time and watch queues build. Select a project to see why it is waiting and who can move it forward.</p>'}</div></div><aside class="inspector panel" id="inspector">${inspector()}</aside></div>`;}
function projectButton(p){return btn(`<span><b>${esc(p.client)}</b><small>${esc(p.service.name)} · ${p.id}</small></span><span class="project-status">${p.priority?'Priority':state.day>p.due&&p.accepted!==undefined&&!p.delivered?'Late':num(p.work[p.stage]||0)>0?num(p.work[p.stage])+' h':state.day-p.entered+' d'}</span>`,'project','projectchip '+(selection?.id===p.id?'selected':''),`data-id="${p.id}" style="--svc:${p.service.color}"`);}
function stageCard(stage,b){const ps=state.projects.filter(p=>p.stage===stage);return `<div class="stage-card ${b?.stage===stage?'bottleneck':''} ${selection?.type==='stage'&&selection.id===stage?'selected':''}"><button class="stage-title" data-action="stage" data-id="${stage}"><span><i>${stageNumber[stage]}</i>${shortLabels[stage]}</span><b>${ps.length}</b></button>${ps.slice(0,2).map(projectButton).join('')||'<p class="emptyqueue">No projects waiting</p>'}${ps.length>2?btn('View all '+ps.length+' projects','stage','small ghost','data-id="'+stage+'"'):''}</div>`;}
function inspector(){if(selection?.type==='project'){const p=state.projects.find(p=>p.id===selection.id);if(p)return projectPanel(p);}if(selection?.type==='stage'){const stage=selection.id,ps=state.projects.filter(p=>p.stage===stage);return `<div class="panelhead"><h2>${shortLabels[stage]}</h2>${btn(icon('close'),'unselect','ghost small','aria-label="Close details"')}</div><div class="inspectbody"><p class="helper">${stageOwner[stage]} · ${ps.length} projects</p>${ps.map(projectButton).join('')||'<div class="empty">This queue is empty.</div>'}${['design','review','quote','delivery'].includes(stage)?btn('Adjust available time','team','soft full'):''}</div>`;}
return `<div class="panelhead"><h2>Inspect the business</h2></div><div class="inspectbody"><div class="hint-number">1</div><h3>Click a project</h3><p>See its price, costs, remaining work and event history.</p><div class="hint-number">2</div><h3>Understand the delay</h3><p>Each stage explains who is responsible and what must happen next.</p><div class="hint-number">3</div><h3>Test a change</h3><p>Branch the scenario before changing capacity or prices. Compare at the same day.</p>${btn(icon('branch')+'Branch this scenario','branch','soft full')}<div class="divider"></div><h3>Current applied setup</h3><div class="minirow"><span>Your time / week</span><b>${state.config.ownerHours} h</b></div><div class="minirow"><span>Designers</span><b>${state.config.designers}</b></div><div class="minirow"><span>Uncertainty</span><b>${state.config.realism?'On':'Off'}</b></div></div>`;}
function nextExplanation(p){if(p.stage==='quote')return 'You need '+num(p.work.quote)+' more hours to prepare this quote.';if(p.stage==='design')return 'The design team needs '+num(p.work.design)+' more work hours.';if(p.stage==='review')return 'You need '+num(p.work.review)+' hours to review the design.';if(p.stage==='approval')return 'Waiting for client approval. You can record approval if the client has responded.';if(p.stage==='production')return 'The supplier needs approximately '+Math.max(0,p.printDuration-(state.day-p.entered))+' more calendar days.';if(p.stage==='delivery')return 'You need '+num(p.work.delivery)+' hours to hand off the finished work.';if(p.stage==='payment')return 'Work is delivered. The remaining balance is due on day '+p.paymentDue+'.';if(p.stage==='complete')return 'Work is delivered and fully paid.';if(p.stage==='lost')return 'The client declined this quote.';return 'The inquiry will move to your quote queue on the next day.';}
function projectPanel(p){const done=['complete','lost'].includes(p.stage);return `<div class="panelhead"><div><div class="eyebrow">${p.id} · ${esc(stageOwner[p.stage])}</div><h2>${esc(p.client)}</h2></div>${btn(icon('close'),'unselect','ghost small','aria-label="Close details"')}</div><div class="inspectbody">${badge(shortLabels[p.stage])}<p>${esc(p.service.name)}</p><p class="helper">${esc(p.service.deliverable)}</p><div class="next-step"><b>What happens next</b><p>${nextExplanation(p)}</p></div><div class="kvs">${[['Agreed price',p.accepted!==undefined?money(p.price):'Not accepted'],['Direct costs',money(p.cost)],['Cash received',money(p.paid)],['Balance owed',money(p.price-p.paid)],['Your hours',num(p.ownerHours)],['Designer hours',num(p.designHours)],['Delivery due',p.accepted!==undefined?'Day '+p.due:'After acceptance'],['At this stage',(state.day-p.entered)+' days']].map(([l,v])=>`<div><label>${l}</label><strong>${v}</strong></div>`).join('')}</div><p class="helper">Direct costs exclude overhead and your time.</p><div class="actions">${!done?btn(p.priority?'Remove priority':'Prioritize work','priority','small','data-id="'+p.id+'"'):''}${!done&&!p.delivered?btn('Extend deadline +3d','deadline','small','data-id="'+p.id+'"'):''}${p.stage==='approval'?btn('Confirm client approval','approve','soft small','data-id="'+p.id+'"'):''}</div><div class="divider"></div><h3>Project timeline</h3><div class="timeline">${[...p.log].reverse().map(e=>`<div class="event"><small>DAY ${e.day}</small><span>${esc(e.text)}</span></div>`).join('')}</div></div>`;}
function projectsView(){return `<div class="project-tools"><label class="search-label">Search client or project<input id="project-search" value="${esc(search)}" placeholder="e.g. Maple or P003"></label><label class="search-label">Show<select id="project-filter">${[['active','Active work'],['all','All projects'],['late','Late deliveries'],['payment','Awaiting payment'],['complete','Completed'],['lost','Declined']].map(([v,n])=>`<option value="${v}" ${filter===v?'selected':''}>${n}</option>`).join('')}</select></label></div><section class="panel" id="project-table">${projectTable()}</section>`;}
function projectTable(){const needle=search.trim().toLowerCase();const ps=state.projects.filter(p=>(!needle||[p.client,p.id,p.service.name].some(x=>x.toLowerCase().includes(needle)))&&(filter==='all'||filter==='active'&&!['lost','complete'].includes(p.stage)||filter==='late'&&p.accepted!==undefined&&!p.delivered&&p.stage!=='lost'&&state.day>p.due||p.stage===filter));return `<div class="tablewrap"><table><thead><tr><th>Client / project</th><th>Service</th><th>Stage</th><th>Responsible</th><th>Agreed price</th><th>Delivery due</th></tr></thead><tbody>${ps.map(p=>`<tr><td>${btn(esc(p.client),'project','table-link','data-id="'+p.id+'"')}<small>${p.id}</small></td><td>${esc(p.service.name)}</td><td>${shortLabels[p.stage]}</td><td>${stageOwner[p.stage]}</td><td>${p.accepted!==undefined?money(p.price):'—'}</td><td>${p.accepted!==undefined?'Day '+p.due:'—'}</td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">No matching projects. Advance the clock or change your filter.</div></td></tr>'}</tbody></table></div>`;}
function financeView(m){return `<div class="metrics">${metric('Cash available',money(state.cash),'Includes funding and client deposits','accent')}${metric('Delivered revenue',money(state.revenue),m.delivered+' projects delivered')}${metric('Operating result',money(m.profit),'Revenue less costs incurred',m.profit<0?'negative':'')}${metric('After your time',money(m.surplus),num(state.ownerHours)+' hours × '+money(state.config.ownerTarget))}</div><div class="two-col"><section class="panel padded"><h2>Why cash and profit differ</h2>${[['Starting cash',state.initialCash],['Owner funding',state.funding],['Client payments received',state.ledger.filter(e=>e.type==='receipt').reduce((n,e)=>n+e.amount,0)],['Costs paid',-state.expenses],['Cash now',state.cash]].map(([l,v])=>`<div class="minirow"><span>${l}</span><b>${money(v)}</b></div>`).join('')}<p class="helper">Deposits enter cash before delivery. Funding increases cash but is never revenue.</p>${btn('Add owner funding','fund','soft')}</section><section class="panel padded"><h2>Time and delivery</h2>${[['Effective earnings / owner hour',money(m.effective)],['Delivery deadlines missed (still open)',m.late],['Overdue final payments',m.overduePayments],['Delivered balances outstanding',money(m.receivable)]].map(([l,v])=>`<div class="minirow"><span>${l}</span><b>${v}</b></div>`).join('')}<p class="helper">A delivered project waiting for payment is not a late delivery. Results expense all incurred costs, including unfinished work. This is a simplified operating model.</p></section></div><section class="panel padded" style="margin-top:18px"><h2>Cash over time</h2>${cashChart()}</section><h2 class="section-title">Monthly results</h2><div class="monthgrid">${Array.from({length:Math.max(1,Math.ceil(state.day/30))},(_,i)=>{const end=state.history.filter(h=>h.day<=(i+1)*30).at(-1),prior=state.history.find(h=>h.day===i*30)||{revenue:0,expenses:0,ownerHours:0};return `<div class="panel padded"><div class="eyebrow">MONTH ${i+1} ${state.day<(i+1)*30?'· PARTIAL':''}</div><h2>${money((end?.revenue||0)-prior.revenue)} revenue</h2><p>Result ${money((end?.revenue||0)-prior.revenue-(end?.expenses||0)+prior.expenses)}<br>Your time ${num((end?.ownerHours||0)-prior.ownerHours)} h</p></div>`;}).join('')}</div><section class="panel"><div class="panelhead"><h2>Cash ledger</h2><span class="tag">LATEST 100 TRANSACTIONS</span></div><div class="tablewrap"><table><thead><tr><th>Day</th><th>Transaction</th><th>Project</th><th>Cash movement</th></tr></thead><tbody>${state.ledger.slice(-100).reverse().map(e=>`<tr><td>${e.day}</td><td>${esc(e.note)}</td><td>${e.project?btn(esc(e.project),'project','table-link','data-id="'+esc(e.project)+'"'):'—'}</td><td class="${e.amount<0?'negative':'positive'}">${money(e.amount)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Run the simulation to see transactions.</td></tr>'}</tbody></table></div></section>`;}
function cashChart(){const vs=QQ.cashSeries(state);const lo=Math.min(0,...vs.map(v=>v.cash)),hi=Math.max(1,...vs.map(v=>v.cash))*1.05;return `<svg class="chart" viewBox="0 0 650 170" role="img" aria-label="Cash balance from day zero to day ${state.day}"><path d="M65 20H630 M65 80H630 M65 140H630" stroke="var(--line)"/><polyline points="${vs.map(v=>`${65+v.day/Math.max(1,state.day)*565},${140-(v.cash-lo)/(hi-lo)*120}`).join(' ')}" fill="none" stroke="var(--green)" stroke-width="2.5"/><text x="0" y="24" class="axislabel">${money(hi)}</text><text x="0" y="144" class="axislabel">${money(lo)}</text><text x="65" y="165" class="axislabel">Day 0</text><text x="575" y="165" class="axislabel">Day ${state.day}</text></svg>`;}
function scenariosTableView(){const row=(s,i)=>{const m=QQ.metrics(s);return `<tr><td><b>${esc(i<0?s.config.name:checkpointInfo[i]?.label||s.config.name)}</b><small>${i<0?'Current run':checkpointInfo[i]?.kind==='automatic'?'Automatic checkpoint':'Saved checkpoint'}</small></td><td>${s.day}</td><td>${money(s.cash)}</td><td>${money(m.profit)}</td><td>${num(s.ownerHours)}</td><td>${m.delivered}</td><td>${m.late}</td><td>${i<0?badge('Active'):btn('Load','load','small','data-index="'+i+'"')+btn('Name / keep','rename-checkpoint','small','data-index="'+i+'"')+btn('Delete','delete-checkpoint','small ghost','data-index="'+i+'"')}</td></tr>`;};const other=saved.at(-1),a=QQ.metrics(state),b=other?QQ.metrics(other):null;return `<div class="banner">Compare at the <b>same day</b> with the same seed. Checkpoints stay frozen until loaded. Your current run is preserved before loading another.</div><section class="panel"><div class="panelhead"><h2>Saved runs</h2>${btn('Save checkpoint','checkpoint','soft')}</div><div class="tablewrap"><table><thead><tr><th>Scenario</th><th>Day</th><th>Cash</th><th>Operating result</th><th>Owner hours</th><th>Delivered</th><th>Late</th><th></th></tr></thead><tbody>${row(state,-1)}${saved.map(row).join('')}</tbody></table></div></section><section class="panel padded" style="margin-top:18px"><h2>What changed?</h2>${other?`<p>Compared with <b>${esc(other.config.name)}</b>: ${money(a.profit-b.profit)} difference in operating result, ${num(state.ownerHours-other.ownerHours)} additional owner hours, and ${a.delivered-b.delivered} additional deliveries.</p>${state.day!==other.day?'<div class="banner warn">These runs are on different days. The difference is not yet a fair comparison.</div>':''}<p class="helper">Measured differences do not prove which decision caused them. Inspect the project histories and work queues.</p>`:'<p class="helper">Save a checkpoint or create a branch to begin a comparison.</p>'}</section>`;}
function scenariosView(){return scenariosTableView()+preservationView();}
function preservationView(){return `<section class="panel padded" style="margin-top:18px"><h2>Preserved workspaces</h2><p class="helper">Opening a backup or example preserves your complete previous workspace here. Identical checkpoints are stored once. The latest ${MEIQQWorkspace.AUTO_LIMIT} automatic checkpoints are retained; named or manually saved checkpoints stay until you delete them.</p>${archives.map((a,i)=>`<div class="archive-row"><div><b>${esc(a.label)}</b><p class="helper">Day ${a.workspace.state.day} · ${a.workspace.saved.length} checkpoints · ${a.workspace.state.projects.length} projects · unfinished draft included</p></div><div class="actions">${btn('Open','open-archive','small',`data-index="${i}"`)}${btn('Export','export-archive','small',`data-index="${i}"`)}${btn('Delete','delete-archive','small ghost',`data-index="${i}"`)}</div></div>`).join('')||'<p class="helper">No preserved workspaces yet.</p>'}${recoveryFiles.length?'<div class="divider"></div><h3>Recovered originals</h3><p class="helper">Malformed draft data is kept intact here. The editable form uses the last applied setup until you correct it.</p>'+recoveryFiles.map((f,i)=>`<div class="archive-row"><span>${esc(f.name)}</span>${btn('Download original','recovery-file','small',`data-index="${i}"`)}</div>`).join(''):''}</section>`;}
function aboutView(){return `<div class="two-col"><section class="panel padded"><h2>Start with one experiment</h2><ol><li>Set service prices, hours, inquiry shares and available capacity.</li><li>Review the draft preview, then apply the setup.</li><li>Step through a day or run a month.</li><li>Inspect the queue that grows and the projects inside it.</li><li>Branch, change one input, restart and compare at the same day.</li></ol><h2>What the numbers mean</h2><p>Inquiries are requests for quotes. Conversion is the share that accept. A deposit is received on acceptance; revenue is recognized on delivery.</p><p>The instant preview uses the same first 30 calendar days and 22 working days as the simulation. It assumes full fulfillment of new demand, excluding renewals, delays and uncertainty.</p><p>Operating result is delivered revenue less all incurred costs, including unfinished work. Owner time is valued separately. No taxes, depreciation or full accrual accounting are modeled.</p></section><section class="panel padded"><h2>Rules you can inspect</h2><p>One tick is a day. Work occurs five days in seven. Projects advance at most one stage per day. Staff capacity is pooled by role.</p><p>Accepted quotes lock their prices, work scope and payment/approval/printing terms. Live changes affect new quotes; labor rates and available hours affect future work.</p><p>Cash shortfalls roll back the whole proposed day. Add explicit funding, then retry. No transactions are duplicated.</p><p>Subscription and repeat cycles begin after payment. Subscription renewals are at least 30 days apart. Late cycles do not overlap.</p><h2>Prototype limits</h2><p>All starting numbers are invented. Named staff, supplier comparisons, borrowing and native Windows/Mac installers remain future work.</p><p>Backups include live projects, cash, checkpoints, unfinished drafts and preserved workspaces. Browser storage depends on the browser and file location; use Backup before moving the app.</p></section></div>`;}
function clock(){const end=state.day>=state.config.months*30;return `<footer class="clock"><div class="clockgroup"><div class="clockday"><b>Day ${state.day} <span>/ ${state.config.months*30}</span></b><small>${recoveryFiles.length?`<div class="banner warn">${recoveryFiles.length} original draft or save file(s) preserved for recovery. ${btn('View recovery files','view','small','data-view="scenarios"')}</div>`:''}${state.blocked?'Cash decision needed':running?'Running':end?'Run complete':'Paused'}</small></div>${btn(icon(running?'pause':'play')+(running?'Pause':'Run'),'play','primary',end?'disabled':'')}${btn(icon('step')+'1 day','step','',end?'disabled':'')}${btn('Finish month','finish','',end?'disabled':'')}<label class="clock-select"><span>Speed</span><select id="speed" aria-label="Simulation speed">${[1,2,4].map(n=>`<option value="${n}" ${speed===n?'selected':''}>${n}×</option>`).join('')}</select></label></div><div class="clockgroup"><label class="clock-select"><span>Horizon</span><select id="horizon" aria-label="Simulation horizon">${[1,3,6,12].map(n=>`<option value="${n}" ${state.config.months===n?'selected':''}>${n} month${n>1?'s':''}</option>`).join('')}</select></label>${btn(icon('reset'),'restart','','aria-label="Restart run" title="Restart with applied settings"')}</div></footer>`;}

function checkpoint(kind='automatic'){MEIQQWorkspace.checkpoint({state,saved,checkpointInfo},kind);}
function modal(html){stop();modalFocus=document.activeElement;$('#modal').innerHTML=`<div class="modalback"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title">${html}<div class="modal-error" id="modal-error" role="alert"></div></section></div>`;setTimeout(()=>$('#modal input, #modal button')?.focus(),0);}
function closeModal(){$('#modal').innerHTML='';modalFocus?.focus();}
function showError(message){const el=$('#modal-error');if($('#modal').firstChild&&el)el.textContent=message;else toast(message);}
function review(){stop();const error=draftError();if(error){toast(error);return;}if(!dirty()){view='map';render();return;}const restartOnly=state.day>0&&(draft.startingCash!==state.config.startingCash||draft.seed!==state.config.seed||draft.months*30<state.day);const names={services:'Services and inquiry mix',ownerHours:'Your available time',ownerTarget:'Value of your time',designers:'Designer count',designerHours:'Designer availability',designerRate:'Labor rate',overhead:'Overhead',startingCash:'Starting cash',conversion:'Conversion',deposit:'Deposit',leadDays:'Delivery promise',inquiries:'New inquiries',acquisition:'Inquiry source',paymentDays:'Payment terms',approvalDays:'Approval timing',printDays:'Print timing',seed:'Workload seed',retention:'Renewals',repeat:'Repeat purchases',realism:'Uncertainty',uncertainty:'Uncertainty switches',name:'Scenario name',months:'Horizon',outreachHours:'Outreach time',leadsPerHour:'Outreach response',priority:'Queue order',quoteHours:'Quoting work',deliveryHours:'Delivery work'};const changes=Object.keys(draft).filter(k=>JSON.stringify(draft[k])!==JSON.stringify(state.config[k]));modal(`<div class="eyebrow">${changes.length} SETTING GROUPS CHANGED</div><h2 id="dialog-title">Apply your business setup</h2><p>A checkpoint of your current run will be saved first.</p><ul class="change-list">${changes.map(k=>`<li>${esc(names[k]||k)}${typeof draft[k]==='number'&&!['conversion','retention','deposit','repeat'].includes(k)?`: <b>${esc(state.config[k])} → ${esc(draft[k])}</b>`:''}</li>`).join('')}</ul><div class="choice-explain"><b>Apply to the current run</b><p>Capacity and labor rates affect upcoming work. New quotes use the updated services and terms. Existing agreements stay intact.</p></div><div class="choice-explain"><b>Apply and start a new run</b><p>Start at day 0 using the new setup. Use the same seed for a comparison.</p></div>${restartOnly?'<div class="banner warn">Starting cash, seed or a shorter horizon changed. Start a new run to apply these.</div>':''}<div class="actions">${btn('Keep editing','close')}${!restartOnly?btn(state.day?'Apply going forward':'Apply setup','apply','soft','data-mode="future"'):''}${btn('Apply & start new run','apply','primary','data-mode="restart"')}</div>`);render();}
function applyDraft(mode){const error=draftError();if(error)throw Error(error);const next=QQ.clone(draft);if(mode==='restart'){checkpoint();state=QQ.fresh(next);}else{const updated=QQ.clone(state);QQ.applyConfig(updated,next);checkpoint();state=updated;}draft=QQ.clone(state.config);selection=null;view='map';closeModal();render();toast(mode==='restart'?'Setup applied. New run ready at day 0.':'Changes applied. Existing commitments preserved.');}
function beginRun(action){stop();if(dirty()){review();return false;}if(state.blocked){cashModal();return false;}if(state.day>=state.config.months*30)return false;view='map';return true;}
function tick(){const advanced=QQ.step(state);save();if(!advanced||state.day>=state.config.months*30)stop();render();if(state.blocked)cashModal();}
function play(){if(running){stop();render();return;}if(!beginRun('play'))return;running=true;timer=setInterval(tick,1000/speed);render();}
function finishMonth(){if(!beginRun('finish'))return;const target=Math.min(state.config.months*30,(Math.floor(state.day/30)+1)*30);while(state.day<target){if(!QQ.step(state))break;}save();render();if(state.blocked)cashModal();else toast('Reached day '+state.day+'. Inspect your queues and results.');}
function cashModal(){const b=state.blocked;if(!b)return;modal(`<div class="eyebrow">RUN PAUSED</div><h2 id="dialog-title">A payment needs funding</h2><p>${esc(b.note)}</p><div class="kvs"><div><label>Payment needed</label><strong>${money(b.amount)}</strong></div><div><label>Cash at that point</label><strong>${money(b.cash)}</strong></div></div><div class="banner warn">Shortfall: <b>${money(b.gap)}</b>. The attempted day was rolled back. Retry after funding; nothing is duplicated.</div><label class="input-field">Owner funding ($)<input id="funding" type="number" min="0.01" max="100000000" step="0.01" value="${Math.max(500,Math.ceil(b.gap))}"></label><p class="helper">Funding increases cash, not profit. The simulation remains paused after funding.</p><div class="actions">${btn('Keep paused','close')}${btn('Add funding','confirm-fund','primary')}</div>`);}
function download(name,data){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function backupPayload(){return MEIQQWorkspace.pack(currentWorkspace(),archives);}
function parseBackup(data){return MEIQQWorkspace.parse(data);}
function importFile(){stop();const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const f=input.files?.[0];if(!f)return;MEIQQWorkspace.checkSize(f.size);const parsed=MEIQQWorkspace.parseText(await f.text());modal(`<h2 id="dialog-title">Open this ${parsed.full?'saved workspace':'setup'}?</h2><p><b>${esc(parsed.state.config.name)}</b> · day ${parsed.state.day} · ${parsed.state.projects.length} projects.</p><p>Your complete current workspace, including checkpoints and unfinished draft, will remain available under Preserved workspaces.</p><div class="actions">${btn('Cancel','close')}${btn('Open backup','confirm-import','primary')}</div>`);pendingImport=parsed;}catch(e){toast(e.message||'The backup could not be read.');}};input.click();}
let pendingImport=null;
function handleInput(el){
 const path=el.dataset?.input;if(!path||loading)return;stop();const parts=path.split('.');let target=draft;for(const p of parts.slice(0,-1))target=target[p];const key=parts.at(-1);
 const value=el.type==='checkbox'?el.checked:key==='recurring'?el.value==='true':el.type==='number'?(el.value.trim()===''?null:Number(el.value)/(el.dataset.percent?100:1)):el.value;
 target[key]=value;
 const error=$('#error-'+el.id);if(error)error.textContent=typeof el.checkValidity==='function'&&!el.checkValidity()?'Enter a valid value in the range shown.':'';
 updatePreview();
}
document.addEventListener('input',e=>{if(e.target.id==='project-search'){search=e.target.value;$('#project-table').innerHTML=projectTable();return;}if(e.target.dataset?.input&&e.target.type!=='checkbox'&&e.target.tagName!=='SELECT')handleInput(e.target);});
document.addEventListener('change',e=>{
 const el=e.target;if(loading)return;
 if(el.dataset?.input){handleInput(el);if(el.dataset.input==='acquisition'||el.type==='checkbox')render();return;}
 if(el.id==='appearance'){if(!['light','dark','terminal'].includes(el.value))return;theme=el.value;document.documentElement.dataset.theme=theme;try{localStorage.setItem(THEME_KEY,theme);}catch(err){toast('Theme applied for this session. Browser storage is unavailable.');}return;}
 if(el.id==='speed'){speed=Number(el.value);if(running){clearInterval(timer);timer=setInterval(tick,1000/speed);}return;}
 if(el.id==='horizon'){stop();const months=Number(el.value);if(months*30<state.day){toast('The horizon must include the current day.');render();return;}state.config.months=months;draft.months=months;save();render();return;}
 if(el.id==='project-filter'){filter=el.value;$('#project-table').innerHTML=projectTable();}
});
document.addEventListener('click',e=>{
 const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(loading)return;
 try{
  if(a==='view'){stop();view=el.dataset.view;render();}
  else if(a==='setup-step'){stop();stepIndex=Number(el.dataset.step);render();}
  else if(a==='team'){stop();view='setup';stepIndex=2;render();}
  else if(a==='review')review();
  else if(a==='apply')applyDraft(el.dataset.mode);
  else if(a==='discard'){draft=QQ.clone(state.config);render();toast('Draft changes cancelled.');}
  else if(a==='add-service'){if(draft.services.length>=20)throw Error('The prototype supports up to 20 services.');draft.services.push({id:'service'+Date.now(),name:'New service',deliverable:'Describe the deliverable',price:350,hours:5,review:1,print:0,weight:0,recurring:false,color:'#647f9a'});expandedService=draft.services.length-1;render();toast('Service added with 0% inquiry share. Open it to edit, then adjust the mix.');}
  else if(a==='duplicate'){const s=QQ.clone(draft.services[Number(el.dataset.index)]);s.id='service'+Date.now();s.name+=' copy';s.weight=0;draft.services.push(s);expandedService=draft.services.length-1;render();}
  else if(a==='remove-service'){if(draft.services.length<=1)throw Error('Keep at least one service.');draft.services.splice(Number(el.dataset.index),1);expandedService=Math.min(expandedService,draft.services.length-1);render();}
  else if(a==='balance'){const n=draft.services.length,part=Math.floor(100/n);draft.services.forEach((s,i)=>s.weight=i===n-1?100-part*(n-1):part);render();}
  else if(a==='play')play();
  else if(a==='step'){if(beginRun('step'))tick();}
  else if(a==='finish')finishMonth();
  else if(a==='stage'){selection={type:'stage',id:el.dataset.id};view='map';render();}
  else if(a==='project'){stop();selection={type:'project',id:el.dataset.id};view='map';render();}
  else if(a==='unselect'){selection=null;render();}
  else if(a==='filter-complete'){stop();view='projects';filter='complete';render();}
  else if(['priority','deadline','approve'].includes(a)){stop();const p=state.projects.find(v=>v.id===el.dataset.id);QQ.intervene(state,p.id,a,a==='deadline'?p.due+3:undefined);render();toast('Project decision recorded.');}
  else if(a==='checkpoint'){checkpoint('manual');render();toast('Checkpoint saved.');}
  else if(a==='branch'){stop();modal(`<h2 id="dialog-title">Branch this scenario</h2><p>Save the current run, then continue in an independent copy. Any setup draft is kept with the new branch.</p><label class="input-field">Scenario name<input id="branch-name" maxlength="100" value="${esc(state.config.name+' · alternative')}"></label><div class="actions">${btn('Cancel','close')}${btn('Create branch','confirm-branch','primary')}</div>`);render();}
  else if(a==='confirm-branch'){const name=$('#branch-name').value.trim();if(!name)throw Error('Enter a scenario name.');checkpoint();state=QQ.clone(state);state.config.name=name;draft.name=name;closeModal();view='setup';render();toast('Branch created; original run preserved.');}
  else if(a==='load'){if(dirty())throw Error('Apply or cancel setup changes before loading a checkpoint.');stop();const next=QQ.restore(saved[Number(el.dataset.index)]);checkpoint();state=next;draft=QQ.clone(state.config);selection=null;render();}
  else if(a==='restart'){stop();if(dirty()){review();return;}modal(`<h2 id="dialog-title">Restart from day 0?</h2><p>Your current run will be saved as a checkpoint. The new run uses the same applied assumptions and seed.</p><div class="actions">${btn('Cancel','close')}${btn('Save & restart','confirm-restart','primary')}</div>`);render();}
  else if(a==='confirm-restart'){checkpoint();state=QQ.fresh(state.config);draft=QQ.clone(state.config);selection=null;view='map';closeModal();render();}
  else if(a==='example'){stop();modal(`<h2 id="dialog-title">Open a worked example?</h2><p>Load a hypothetical studio on day 12, with projects to inspect. Your complete workspace will be preserved inside the app, including checkpoints and unfinished inputs.</p><div class="actions">${btn('Cancel','close')}${btn('Preserve & open example','confirm-example','primary')}</div>`);render();}
  else if(a==='confirm-example'){archiveCurrent();state=QQ.fresh();saved=[];checkpointInfo=[];recoveryFiles=[];recoveryRaw=null;for(let i=0;i<12;i++)QQ.step(state);draft=QQ.clone(state.config);view='map';selection=null;closeModal();render();}
  else if(a==='cash')cashModal();
  else if(a==='fund'){modal(`<h2 id="dialog-title">Add owner funding</h2><p>Cash increases. Revenue and profit do not change.</p><label class="input-field">Amount ($)<input id="funding" type="number" min="0.01" max="100000000" step="0.01" value="1000"></label><div class="actions">${btn('Cancel','close')}${btn('Add funding','confirm-fund','primary')}</div>`);render();}
  else if(a==='confirm-fund'){const f=$('#funding');if(!f.checkValidity())return f.reportValidity();QQ.fund(state,Number(f.value));closeModal();render();toast('Funding added. Resume when ready.');}
  else if(a==='backup'){download('MEIQQ-Backup-Day-'+state.day+'.json',MEIQQWorkspace.serialize(currentWorkspace(),archives));toast('Backup download requested. Unfinished inputs and preserved workspaces are included.');}
  else if(a==='recover')download('MEIQQ-original-save.json',recoveryRaw);
  else if(a==='import')importFile();
  else if(a==='confirm-import'){if(!pendingImport)throw Error('Choose a backup first.');openImportedWorkspace(pendingImport);pendingImport=null;view=state.day?'map':'setup';closeModal();render();toast('Backup opened. Previous workspace preserved in Scenarios.');}
else if(a==='open-archive'){
   const index=Number(el.dataset.index),item=archives[index];if(!item)throw Error('Workspace not found.');
   const next=QQ.clone(item.workspace),rest=archives.filter((_,i)=>i!==index);
   MEIQQWorkspace.archive(rest,currentWorkspace());installWorkspace({...next,archives:rest});recoveryRaw=null;selection=null;render();toast('Preserved workspace reopened.');
  }
  else if(a==='export-archive'){const item=archives[Number(el.dataset.index)];if(!item)throw Error('Workspace not found.');download('MEIQQ-Preserved-Workspace.json',MEIQQWorkspace.serialize(item.workspace));}
  else if(a==='recovery-file'){const file=recoveryFiles[Number(el.dataset.index)];if(!file)throw Error('Recovery file not found.');download('MEIQQ-Recovered-Original.json',file.text);}
  else if(a==='rename-checkpoint'){const i=Number(el.dataset.index);modal(`<h2 id="dialog-title">Name this checkpoint</h2><label class="input-field">Name<input id="checkpoint-name" maxlength="100" value="${esc(checkpointInfo[i].label)}"></label><div class="actions">${btn('Cancel','close')}${btn('Save name','confirm-rename','primary',`data-index="${i}"`)}</div>`);}
  else if(a==='confirm-rename'){const i=Number(el.dataset.index),label=$('#checkpoint-name').value.trim();if(!label||label.length>100)throw Error('Enter a name up to 100 characters.');checkpointInfo[i]={label,kind:'manual'};closeModal();render();}
  else if(['delete-checkpoint','delete-archive'].includes(a)){const kind=a==='delete-checkpoint'?'checkpoint':'workspace';modal(`<h2 id="dialog-title">Delete this ${kind}?</h2><p>This removes the saved copy from this browser. Existing downloaded backups keep their copy.</p><div class="actions">${btn('Cancel','close')}${btn('Delete saved copy','confirm-delete','primary',`data-kind="${kind}" data-index="${Number(el.dataset.index)}"`)}</div>`);}
  else if(a==='confirm-delete'){const i=Number(el.dataset.index);if(el.dataset.kind==='checkpoint'){saved.splice(i,1);checkpointInfo.splice(i,1);}else archives.splice(i,1);closeModal();render();}
  else if(a==='close'){closeModal();render();}
  if(['apply','discard','add-service','duplicate','remove-service','balance','priority','deadline','approve','checkpoint','confirm-branch','load','confirm-restart','confirm-example','confirm-fund','confirm-import','open-archive','confirm-rename','confirm-delete'].includes(a))save();
 }catch(err){showError(err.message||'The action could not be completed.');}
});
document.addEventListener('keydown',e=>{if(!$('#modal').firstChild)return;if(e.key==='Escape'){closeModal();render();}if(e.key==='Tab'){const els=[...document.querySelectorAll('#modal button, #modal input, #modal select')].filter(el=>!el.disabled);if(!els.length)return;if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus();}}});
window.addEventListener('beforeunload',e=>{save();if(storeError||saveStatus==='saving'||saveStatus==='pending'||recoveryRaw){e.preventDefault?.();e.returnValue='';}});
render();
const appReady=initializeStorage();
